import { designTokens, getThemeColors } from "./tokens.ts";

const kebab = (name: string) => name.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`);

/** Stable serialization. This module is also executable by Node's TS support. */
export function generateThemeCss(): string {
  const lines = [
    "/* Generated by scripts/generate-css.mjs. Edit src/tokens.ts, then run generate:css. */",
    ":root {",
    `  --game-font-family: ${designTokens.typography.fontFamily};`,
    `  --game-font-fun-family: ${designTokens.typography.funFontFamily};`,
  ];
  for (const [scale, value] of Object.entries(designTokens.spacing)) {
    lines.push(`  --game-space-${scale}: ${value}px;`);
  }
  for (const [scale, value] of Object.entries(designTokens.radii)) {
    lines.push(`  --game-radius-${scale}: ${value}px;`);
  }
  for (const [scale, value] of Object.entries(designTokens.typography.fontSizes)) {
    lines.push(`  --game-font-size-${scale}: ${value / 16}rem;`);
  }
  for (const [weight, value] of Object.entries(designTokens.typography.fontWeights)) {
    lines.push(`  --game-font-weight-${weight}: ${value};`);
  }
  for (const [name, value] of Object.entries(designTokens.motion)) {
    lines.push(`  --game-motion-${kebab(name)}: ${value}ms;`);
  }
  lines.push(
    "  --motion-background-crossfade: var(--game-motion-background-crossfade);",
    `  --game-touch-target: ${designTokens.minimumTouchTarget}px;`,
    "}",
    "",
  );
  for (const scheme of ["light", "dark"] as const) {
    lines.push(scheme === "light" ? ":root,\n.light {" : ".dark {");
    lines.push(`  color-scheme: ${scheme};`);
    for (const [role, value] of Object.entries(getThemeColors(scheme))) {
      lines.push(`  --${kebab(role)}: ${value};`);
    }
    lines.push(`  --radius: ${designTokens.radii.lg}px;`, "}", "");
  }
  lines.push(
    "@theme inline {",
    "  --font-sans: var(--game-font-family);",
    "  --color-player-mark: var(--player-mark);",
    "  --color-computer-mark: var(--computer-mark);",
    "  --color-board-grid: var(--board-grid);",
    "  --color-board-overlay: var(--board-overlay);",
  );
  for (const scale of Object.keys(designTokens.radii)) {
    lines.push(`  --radius-${scale}: var(--game-radius-${scale});`);
  }
  lines.push("}", "");
  return lines.join("\n");
}
